-- SegueIT Projects: one-time database setup for Neon
-- Creates every table, the first root admin (satwik.narang@segueit.com / change@123)
-- and the empty SegueIT organization with its default statuses and priorities.
--
-- All tables live in their own schema, "ptms", so they never clash with other tables in the
-- database. DATABASE_URL and DIRECT_URL must therefore end with &schema=ptms.
--
-- How to use: Neon console -> your project -> SQL Editor -> select the database your
-- DATABASE_URL points to -> paste this whole file -> Run. Run it only once. The file is 152 lines and ends with COMMIT;
-- check the editor shows the same before you click Run.
-- Change the password after your first sign-in (Profile -> Change password).

BEGIN;
CREATE SCHEMA IF NOT EXISTS "ptms";
CREATE TABLE "ptms"."Organization" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "logoUrl" TEXT, "primaryColor" TEXT, "timezone" TEXT NOT NULL, "weekStartsOn" INTEGER NOT NULL, "workingHoursPerDay" DOUBLE PRECISION NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."User" ("id" TEXT NOT NULL, "organizationId" TEXT, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "jobTitle" TEXT, "avatarUrl" TEXT, "role" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "hourlyRate" DOUBLE PRECISION, "lastLoginAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."AuthToken" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "purpose" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuthToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."RefreshToken" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "userAgent" TEXT, "ipAddress" TEXT, "persistent" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RefreshToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Lookup" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "type" TEXT NOT NULL, "name" TEXT NOT NULL, "color" TEXT NOT NULL, "category" TEXT, "position" INTEGER NOT NULL DEFAULT 0, "isDefault" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Lookup_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Project" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "color" TEXT, "statusId" TEXT NOT NULL, "ownerId" TEXT NOT NULL, "startDate" TIMESTAMP(3), "endDate" TIMESTAMP(3), "budgetHours" DOUBLE PRECISION, "isArchived" BOOLEAN NOT NULL DEFAULT false, "taskCounter" INTEGER NOT NULL DEFAULT 0, "issueCounter" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."ProjectMember" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "userId" TEXT NOT NULL, "role" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProjectMember_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."ProjectFavorite" ("userId" TEXT NOT NULL, "projectId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProjectFavorite_pkey" PRIMARY KEY ("userId","projectId"));
CREATE TABLE "ptms"."Milestone" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "startDate" TIMESTAMP(3), "dueDate" TIMESTAMP(3) NOT NULL, "ownerId" TEXT, "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Milestone_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."TaskList" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "milestoneId" TEXT, "name" TEXT NOT NULL, "color" TEXT, "position" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TaskList_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Task" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "taskListId" TEXT, "milestoneId" TEXT, "parentId" TEXT, "number" INTEGER NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "statusId" TEXT NOT NULL, "priorityId" TEXT NOT NULL, "startDate" TIMESTAMP(3), "dueDate" TIMESTAMP(3), "dueSoonNotifiedFor" TIMESTAMP(3), "overdueNotifiedFor" TIMESTAMP(3), "estimatedHours" DOUBLE PRECISION, "progress" INTEGER NOT NULL DEFAULT 0, "position" DOUBLE PRECISION NOT NULL DEFAULT 0, "createdById" TEXT NOT NULL, "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Task_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."TaskAssignee" ("taskId" TEXT NOT NULL, "userId" TEXT NOT NULL, "assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TaskAssignee_pkey" PRIMARY KEY ("taskId","userId"));
CREATE TABLE "ptms"."TaskDependency" ("id" TEXT NOT NULL, "predecessorId" TEXT NOT NULL, "successorId" TEXT NOT NULL, "type" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TaskDependency_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Issue" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "number" INTEGER NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "statusId" TEXT NOT NULL, "priorityId" TEXT NOT NULL, "severityId" TEXT NOT NULL, "reporterId" TEXT NOT NULL, "assigneeId" TEXT, "milestoneId" TEXT, "taskId" TEXT, "dueDate" TIMESTAMP(3), "dueSoonNotifiedFor" TIMESTAMP(3), "overdueNotifiedFor" TIMESTAMP(3), "resolvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Issue_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."TimeEntry" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "projectId" TEXT NOT NULL, "taskId" TEXT, "issueId" TEXT, "date" TIMESTAMP(3) NOT NULL, "minutes" INTEGER NOT NULL, "notes" TEXT, "isBillable" BOOLEAN NOT NULL DEFAULT true, "approvalStatus" TEXT NOT NULL, "approvedById" TEXT, "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TimeEntry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Comment" ("id" TEXT NOT NULL, "authorId" TEXT NOT NULL, "taskId" TEXT, "issueId" TEXT, "body" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Comment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Activity" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "projectId" TEXT, "actorId" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT NOT NULL, "action" TEXT NOT NULL, "summary" TEXT NOT NULL, "metadata" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Activity_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Notification" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "body" TEXT, "link" TEXT, "readAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Automation" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "name" TEXT NOT NULL, "trigger" TEXT NOT NULL, "triggerValue" TEXT, "action" TEXT NOT NULL, "actionValue" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "runCount" INTEGER NOT NULL DEFAULT 0, "lastRunAt" TIMESTAMP(3), "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Automation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."CustomField" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "options" TEXT, "position" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CustomField_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."CustomFieldValue" ("id" TEXT NOT NULL, "fieldId" TEXT NOT NULL, "taskId" TEXT NOT NULL, "value" TEXT NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CustomFieldValue_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ptms"."Meeting" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "projectId" TEXT, "title" TEXT NOT NULL, "description" TEXT, "type" TEXT NOT NULL, "link" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3) NOT NULL, "reminderSentAt" TIMESTAMP(3), "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Meeting_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Organization_slug_key" ON "ptms"."Organization"("slug");
CREATE UNIQUE INDEX "User_email_key" ON "ptms"."User"("email");
CREATE INDEX "User_organizationId_idx" ON "ptms"."User"("organizationId");
CREATE UNIQUE INDEX "AuthToken_tokenHash_key" ON "ptms"."AuthToken"("tokenHash");
CREATE INDEX "AuthToken_userId_idx" ON "ptms"."AuthToken"("userId");
