CREATE INDEX "Project_organizationId_isArchived_idx" ON "ptms"."Project"("organizationId", "isArchived");
CREATE UNIQUE INDEX "Project_organizationId_key_key" ON "ptms"."Project"("organizationId", "key");
CREATE INDEX "ProjectMember_userId_idx" ON "ptms"."ProjectMember"("userId");
CREATE UNIQUE INDEX "ProjectMember_projectId_userId_key" ON "ptms"."ProjectMember"("projectId", "userId");
CREATE INDEX "ProjectFavorite_projectId_idx" ON "ptms"."ProjectFavorite"("projectId");
CREATE INDEX "Milestone_projectId_dueDate_idx" ON "ptms"."Milestone"("projectId", "dueDate");
CREATE INDEX "TaskList_projectId_idx" ON "ptms"."TaskList"("projectId");
CREATE INDEX "Task_projectId_statusId_idx" ON "ptms"."Task"("projectId", "statusId");
CREATE INDEX "Task_dueDate_idx" ON "ptms"."Task"("dueDate");
