CREATE INDEX "TaskAssignee_userId_idx" ON "ptms"."TaskAssignee"("userId");
CREATE UNIQUE INDEX "TaskDependency_predecessorId_successorId_key" ON "ptms"."TaskDependency"("predecessorId", "successorId");
CREATE INDEX "Issue_projectId_statusId_idx" ON "ptms"."Issue"("projectId", "statusId");
CREATE INDEX "Issue_assigneeId_idx" ON "ptms"."Issue"("assigneeId");
CREATE UNIQUE INDEX "Issue_projectId_number_key" ON "ptms"."Issue"("projectId", "number");
CREATE INDEX "TimeEntry_userId_date_idx" ON "ptms"."TimeEntry"("userId", "date");
