CREATE INDEX "Activity_organizationId_createdAt_idx" ON "ptms"."Activity"("organizationId", "createdAt");
CREATE INDEX "Activity_projectId_createdAt_idx" ON "ptms"."Activity"("projectId", "createdAt");
CREATE INDEX "Notification_userId_readAt_idx" ON "ptms"."Notification"("userId", "readAt");
CREATE INDEX "Automation_projectId_trigger_isActive_idx" ON "ptms"."Automation"("projectId", "trigger", "isActive");
CREATE INDEX "CustomField_projectId_position_idx" ON "ptms"."CustomField"("projectId", "position");
CREATE INDEX "CustomFieldValue_taskId_idx" ON "ptms"."CustomFieldValue"("taskId");
